INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind alle Datenarten strukturiert?', 2, '[{"text": "Nein", "correct": true, "because": "Unstrukturierte und halbstrukturierte existieren"}, {"text": "Ja", "correct": false, "because": "Verschiedene Typen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Unterscheidung von Datenarten?', 3, '[{"text": "Effiziente Verarbeitung", "correct": true, "because": "Passende Methoden wählen"}, {"text": "Hardware optimieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Netzwerk sichern", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenarten gibt es?', 5, '[{"text": "Strukturierte", "correct": true, "because": "Tabellarisch organisiert"}, {"text": "Unstrukturierte", "correct": true, "because": "z. B. Multimedia"}, {"text": "Physische", "correct": false, "because": "Kein Datentyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Strukturierte Daten sind tabellarisch. b) Unstrukturierte Daten sind immer Bilder.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unstrukturierte können auch Texte sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit mit Datenarten?', 4, '[{"text": "Verarbeitungsanforderungen", "correct": false, "because": "Entscheidend für Methode"}, {"text": "Speicherbedarf", "correct": false, "because": "Beeinflusst Ressourcen"}, {"text": "Bildschirmdesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob halbstrukturierte Daten Tabellen sind?', 2, '[{"text": "Nein", "correct": true, "because": "z. B. JSON ist flexibel"}, {"text": "Ja", "correct": false, "because": "Nicht streng tabellarisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenart passt zu einer Datenbank?', 3, '[{"text": "Strukturierte", "correct": true, "because": "Tabellenformat ideal"}, {"text": "Unstrukturierte", "correct": false, "because": "Schwerer zu verwalten"}, {"text": "Analoge", "correct": false, "because": "Nicht digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele gehören zu unstrukturierten Daten?', 5, '[{"text": "Videos", "correct": true, "because": "Keine feste Struktur"}, {"text": "E-Mails", "correct": true, "because": "Text mit variabler Form"}, {"text": "SQL-Tabellen", "correct": false, "because": "Strukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Strukturierte Daten sind leicht analysierbar. b) Unstrukturierte Daten sind nutzlos. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unstrukturierte sind wertvoll"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Verwaltung von Datenarten?', 4, '[{"text": "Speicherlösung", "correct": false, "because": "Datenablage nötig"}, {"text": "Verarbeitungstool", "correct": false, "because": "Analyse erforderlich"}, {"text": "Kaffeemaschine", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind halbstrukturierte Daten dasselbe wie strukturierte?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibler als strukturierte"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Organisation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenarten eignen sich für Big Data?', 4, '[{"text": "Unstrukturierte", "correct": true, "because": "Große Mengen wie Videos"}, {"text": "Halbstrukturierte", "correct": true, "because": "z. B. Logs"}, {"text": "Analoge", "correct": false, "because": "Nicht digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass strukturierte Daten immer klein sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch groß sein"}, {"text": "Ja", "correct": false, "because": "Größe unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Verarbeitung von Datenarten?', 3, '[{"text": "Passende Tools", "correct": true, "because": "Effizienz entscheidend"}, {"text": "Schnelle Hardware", "correct": false, "because": "Sekundär"}, {"text": "Minimale Kosten", "correct": false, "because": "Qualität wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unstrukturierte Daten sind schwer analysierbar. b) Strukturierte Daten sind immer aktuell.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aktualität nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenarten sind für Dokumente typisch?', 5, '[{"text": "Strukturierte", "correct": true, "because": "z. B. Tabellen in Berichten"}, {"text": "Halbstrukturierte", "correct": true, "because": "z. B. XML-Dokumente"}, {"text": "Mechanische", "correct": false, "because": "Kein Datentyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Analyse unwichtig?', 3, '[{"text": "Datenstruktur", "correct": false, "because": "Bestimmt Methode"}, {"text": "Datenmenge", "correct": false, "because": "Beeinflusst Aufwand"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind unstrukturierte Daten immer groß?', 3, '[{"text": "Nein", "correct": true, "because": "Können auch klein sein"}, {"text": "Ja", "correct": false, "because": "Größe variabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob halbstrukturierte Daten in Datenbanken passen?', 2, '[{"text": "Ja", "correct": true, "because": "z. B. NoSQL-Datenbanken"}, {"text": "Nein", "correct": false, "because": "Flexibel speicherbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Struktur bei Datenarten?', 4, '[{"text": "Beeinflusst Verarbeitung", "correct": true, "because": "Struktur bestimmt Methode"}, {"text": "Erhöht Speicher", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Ändert Hardware", "correct": false, "because": "Irrelevant"}]');
